package com.gameaggregator.authorizationservice.infrastructure;
import com.gameaggregator.authorizationservice.api.AuthorizationDtos.AccessContext;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpHeaders;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class TenantAccessClient{private final RestClient client;public TenantAccessClient(RestClient.Builder builder,@Value("${clients.tenant-service.url:http://localhost:8082}")String url){client=builder.baseUrl(url).build();}public AccessContext access(UUID tenantId,String authorization){return client.get().uri(u->u.path("/internal/access-context").queryParam("tenantId",tenantId).build()).header(HttpHeaders.AUTHORIZATION,authorization).retrieve().body(Envelope.class).data();}private record Envelope(boolean success,AccessContext data,Object meta){}}
